package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"html/template"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
)

var (
	templateCache = make(map[string]*template.Template)
	cacheMu       sync.RWMutex
	uploadDir     = os.Getenv("UPLOAD_DIR")
)

func init() {
	if uploadDir == "" {
		uploadDir = "/tmp/uploads"
	}
	os.MkdirAll(uploadDir, 0755)
}

// generateToken creates a random filename to prevent path traversal
func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	defer file.Close()

	// Extract extension from original filename
	parts := strings.Split(header.Filename, ".")
	ext := ""
	if len(parts) > 1 {
		ext = "." + parts[len(parts)-1]
	}

	// Use random token for storage name
	token := generateToken()
	storageName := token + ext
	storagePath := uploadDir + "/" + storageName

	dst, err := os.Create(storagePath)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer dst.Close()

	io.Copy(dst, file)

	// Return the download URL using original filename for display
	// The 'name' parameter is used for Content-Disposition only
	downloadURL := fmt.Sprintf("/download/%s?name=%s", storageName, header.Filename)
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"url": "%s", "token": "%s"}`, downloadURL, token)
}

func downloadHandler(w http.ResponseWriter, r *http.Request) {
	// Path: /download/{storageName}
	path := strings.TrimPrefix(r.URL.Path, "/download/")
	if path == "" {
		http.Error(w, "Not found", 404)
		return
	}

	// VULNERABILITY: path is not sanitized - allows path traversal
	// e.g., /download/../../etc/passwd
	fullPath := uploadDir + "/" + path

	if _, err := os.Stat(fullPath); os.IsNotExist(err) {
		http.Error(w, "Not found", 404)
		return
	}

	displayName := r.URL.Query().Get("name")
	if displayName == "" {
		displayName = path
	}

	w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, displayName))
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("X-Content-Type-Options", "nosniff")

	f, err := os.Open(fullPath)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer f.Close()
	io.Copy(w, f)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/upload", uploadHandler)
	http.HandleFunc("/download/", downloadHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
